#include <torch/csrc/autograd/custom_function.h>
#include "pytorch_npu_helper.hpp"
#include <torch/extension.h>

at::Tensor conv_depthwise_2d_asymmetric_input_square_kernel_custom_impl_npu(const at::Tensor& x,
                                                                            const at::Tensor& weight,
                                                                            int64_t stride,
                                                                            int64_t padding) {
    TORCH_CHECK(x.dim() == 4, "x must be NCHW");
    TORCH_CHECK(weight.dim() == 4, "weight must be [C,1,Kh,Kw] for depthwise");
    int64_t N = x.size(0);
    int64_t C = x.size(1);
    int64_t H = x.size(2);
    int64_t W = x.size(3);
    int64_t Kh = weight.size(2);
    int64_t Kw = weight.size(3);
    int64_t Ho = (H + 2 * padding - Kh) / stride + 1;
    int64_t Wo = (W + 2 * padding - Kw) / stride + 1;

    at::Tensor y = at::empty({N, C, Ho, Wo}, x.options());

    // 传入两个整数属性：stride与padding
    EXEC_NPU_CMD(aclnnConvDepthwise2dAsymmetricInputSquareKernelCustom, x, weight, y, (int)stride, (int)padding);
    return y;
}

